const r = $input.first().json;

let text =
  r.output_text ??
  r.outputText ??
  r.text ??
  r?.outputs?.[0]?.text ??
  "";

if (!text && Array.isArray(r.steps)) {
  const step = r.steps.find(s => s.type === "model_output");
  if (step && Array.isArray(step.content)) {
    const part = step.content.find(c => c.type === "text");
    if (part?.text) text = part.text;
  }
}

if (!text) {
  throw new Error(
    "A Gemini respondeu sem output_text. Resposta recebida: " +
    JSON.stringify(r).slice(0, 1500)
  );
}

const cleaned = String(text)
  .replace(/^```json\s*/i, "")
  .replace(/^```\s*/i, "")
  .replace(/\s*```$/i, "")
  .trim();

let content;

try {
  content = JSON.parse(cleaned);
} catch (e) {
  throw new Error(
    "A Gemini retornou conteúdo que não pôde ser convertido em JSON. Início da resposta: " +
    cleaned.slice(0, 1000)
  );
}

return [{
  json: {
    ...content,
    gerado_por: "Google Gemini API",
    modelo: r.model || "gemini-3.8-flash",
    gerado_em: new Date().toISOString()
  }
}];

const d = $input.first().json;

const obrigatorios = [
  "titulo",
  "gancho",
  "roteiro",
  "legenda",
  "cta",
  "hashtags",
  "ideia_visual",
  "duracao_segundos"
];

const faltantes = obrigatorios.filter(
  k => d[k] === undefined || d[k] === null ||
       (typeof d[k] === "string" && d[k].trim() === "") ||
       (Array.isArray(d[k]) && d[k].length === 0)
);

if (faltantes.length) {
  throw new Error("QA reprovado. Campos ausentes ou vazios: " + faltantes.join(", "));
}

if (!Array.isArray(d.hashtags)) {
  throw new Error("QA reprovado. hashtags deve ser uma lista.");
}

if (!Number.isInteger(d.duracao_segundos) || d.duracao_segundos < 10 || d.duracao_segundos > 180) {
  throw new Error("QA reprovado. duracao_segundos deve ser um número inteiro entre 10 e 180.");
}

if (String(d.gancho).length < 15) {
  throw new Error("QA reprovado. Gancho muito curto.");
}

if (String(d.roteiro).length < 180) {
  throw new Error("QA reprovado. Roteiro muito curto.");
}

return [{
  json: {
    ...d,
    qa: {
      aprovado: true,
      campos_verificados: obrigatorios,
      status: "APROVADO"
    },
    status: "CONTEUDO_REAL_PRONTO"
  }
}];

const d = $input.first().json;

return [{
  json: {
    projeto: "RUPTURA ONE",
    status: d.status,
    gerado_por: d.gerado_por,
    modelo: d.modelo,
    titulo: d.titulo,
    gancho: d.gancho,
    roteiro: d.roteiro,
    legenda: d.legenda,
    cta: d.cta,
    hashtags: d.hashtags,
    ideia_visual: d.ideia_visual,
    duracao_segundos: d.duracao_segundos,
    qa: d.qa,
    gerado_em: d.gerado_em
  }
}];
